%--------------------------------------------------------------------------
%calcSensitivityAndBias
%By: Brielle Ferguson
%Date: 1/5/25
%Will take the trial structure generated by readAnalyzePlotBehData, and
%calculate sensitivity and bias using signal detection theory (SDT) in the set of trials. 
%Assumptions: 
% - treats left side as signal and right side as noise.
%Inputs:
% - trials: data structure with trial information from a behavioral session
%Outputs:
% - SDT: a structure with the following fields
%       - sensitivity: z score(hit rate) - z score(false alarm rate)
%       - bias: -(z score (leftHitRate) + z score (leftFARate)) / 2;
%-------------------------------------------------------------------------

function SDT = calcSensitivityAndBias(trials)
%treating LEFT cue as s and right cue as n  
%left cue, correct: Hit, left cue, incorrect: Miss, right cue, incorrect:
%false alarm, right cue, correct: correct rejection

%will use these values classify trials
for i= 1:length(trials)
    if strcmp(trials(i).accuracy,'Correct') && strcmp(trials(i).choice,'L')
        trials(i).leftSignal = 'Hit';
    elseif strcmp(trials(i).accuracy,'Incorrect') && strcmp(trials(i).choice,'L')
        trials(i).leftSignal = 'Miss';
    elseif strcmp(trials(i).accuracy,'Incorrect') && strcmp(trials(i).choice,'R')
        trials(i).leftSignal = 'FA';     
    elseif strcmp(trials(i).accuracy,'Correct') && strcmp(trials(i).choice,'R')
        trials(i).leftSignal = 'CR';
    end
end

%pull the response types for left signal
leftSignalResponses = getFieldFromTrialStructure(trials,'leftSignal');

%get number of response types for left 
leftHit = length(find(~cellfun(@isempty, strfind(leftSignalResponses, 'Hit')))) + 0.5;
leftMiss = length(find(~cellfun(@isempty, strfind(leftSignalResponses, 'Miss')))) + 0.5;
leftFA = length(find(~cellfun(@isempty, strfind(leftSignalResponses, 'FA')))) + 0.5;
leftCR = length(find(~cellfun(@isempty, strfind(leftSignalResponses, 'CR'))))+ 0.5;

%calculate hit rate and false alarm rate  
leftHitRate = leftHit/(leftHit + leftMiss);
leftFARate = leftFA/(leftFA+leftCR);

% Compute Z-scores for hit rate and false alarm rate
z_leftHitRate = norminv(leftHitRate);
z_leftFARate = norminv(leftFARate);

% Compute sensitivity (d')
SDT.sensitivity = z_leftHitRate - z_leftFARate;

% Compute bias (c) for the left side, positive means left bias while negative is
% right 
SDT.bias_L = -(z_leftHitRate + z_leftFARate) / 2;

%print values 
% disp(['Sensitivity (d''): ', num2str(SDT.sensitivity)]);
% disp(['Bias (c) Left: ', num2str(SDT.bias_L)]);

end